+#!/usr/bin/env node
+import { Pool } from "pg";
+import * as fs from "fs";
+import * as path from "path";
+import { introspectSchema } from "../src/db/schema-gen.js";
+
+async function updateSchema() {
+  const dbUrl = process.env.DATABASE_URL;
+  if (!dbUrl) {
+    throw new Error("DATABASE_URL environment variable is required");
+  }
+
+  const pool = new Pool({ connectionString: dbUrl });
+
+  try {
+    const schema = await introspectSchema(pool);
+
+    const outputFile = path.join(__dirname, "../src/db/generated/schema.ts");
+    let content = "// Auto-generated schema types - do not edit manually\n// Run: npx ts-node scripts/update-schema.ts\n\n";
+
+    for (const [tableName, columns] of Object.entries(schema)) {
+      const typeName = tableNameToType(tableName);
+      const fields = columns.map((col) => {
+        const optional = col.nullable ? "?" : "";
+        return `  ${col.name}${optional}: ${col.type};`;
+      });
+
+      content += `export interface ${typeName}Row {\n${fields.join("\n")}\n}\n\n`;
+    }
+
+    fs.writeFileSync(outputFile, content);
+    console.log(`✓ Updated ${outputFile} with ${Object.keys(schema).length} tables`);
+  } finally {
+    await pool.end();
+  }
+}
+
+function tableNameToType(tableName: string): string {
+  return tableName
+    .split("_")
+    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
+    .join("");
+}
+
+updateSchema().catch((err) => {
+  console.error("Schema update failed:", err.message);
+  process.exit(1);
+});
