--- /dev/null
+++ b/src/db/query-validator.ts
@@ -0,0 +1,86 @@
+import type { TableSchema } from "./schema-gen.js";
+
+function parseSelectColumns(sql: string): { table: string | null; columns: string[] } {
+  const selectMatch = sql.match(/SELECT\s+([\w\s,.*]+?)\s+FROM\s+(\w+)/i);
+
+  if (!selectMatch) {
+    return { table: null, columns: [] };
+  }
+
+  const columnsStr = selectMatch[1];
+  const tableName = selectMatch[2];
+
+  if (columnsStr.trim() === "*") {
+    return { table: tableName, columns: ["*"] };
+  }
+
+  const columns = columnsStr
+    .split(",")
+    .map((col) => {
+      const colName = col.trim().split(/\s+AS\s+|\s+/i)[0];
+      return colName;
+    })
+    .filter((col) => col.length > 0);
+
+  return { table: tableName, columns };
+}
+
+function parseInsertUpdateColumns(sql: string): { table: string | null; columns: string[] } {
+  let match = sql.match(/INSERT\s+INTO\s+(\w+)\s*\(\s*([\w\s,]+)\s*\)/i);
+  if (match) {
+    const columns = match[2]
+      .split(",")
+      .map((col) => col.trim())
+      .filter((col) => col.length > 0);
+    return { table: match[1], columns };
+  }
+
+  match = sql.match(/UPDATE\s+(\w+)\s+SET\s+([\w\s,=.]+)/i);
+  if (match) {
+    const table = match[1];
+    const setClause = match[2];
+    const columns = setClause
+      .split(",")
+      .map((part) => part.split("=")[0].trim())
+      .filter((col) => col.length > 0);
+    return { table, columns };
+  }
+
+  return { table: null, columns: [] };
+}
+
+export function validateQuery(sql: string, schema: TableSchema): void {
+  const upperSql = sql.toUpperCase();
+  let parsed: { table: string | null; columns: string[] };
+
+  if (upperSql.includes("SELECT")) {
+    parsed = parseSelectColumns(sql);
+  } else if (upperSql.includes("INSERT") || upperSql.includes("UPDATE")) {
+    parsed = parseInsertUpdateColumns(sql);
+  } else {
+    return;
+  }
+
+  if (!parsed.table) {
+    throw new Error(`Query validation: could not parse table name from SQL: ${sql}`);
+  }
+
+  if (!schema[parsed.table]) {
+    throw new Error(
+      `Query validation: table '${parsed.table}' does not exist. Available: ${Object.keys(schema).join(", ")}`,
+    );
+  }
+
+  const tableSchema = schema[parsed.table];
+  const validColumns = new Set(tableSchema.map((col) => col.name));
+
+  if (!parsed.columns.includes("*")) {
+    for (const col of parsed.columns) {
+      if (!validColumns.has(col)) {
+        throw new Error(
+          `Query validation: column '${col}' does not exist in table '${parsed.table}'. Available: ${Array.from(validColumns).join(", ")}`,
+        );
+      }
+    }
+  }
+}
