@@ -0,0 +1,70 @@
+import { Pool } from "pg";
+
+export interface ColumnInfo {
+  name: string;
+  type: string;
+  nullable: boolean;
+}
+
+export interface TableSchema {
+  [tableName: string]: ColumnInfo[];
+}
+
+// Introspect Postgres schema at runtime
+export async function introspectSchema(pool: Pool): Promise<TableSchema> {
+  const result = await pool.query(`
+    SELECT
+      table_name,
+      column_name,
+      data_type,
+      is_nullable
+    FROM information_schema.columns
+    WHERE table_schema = 'public'
+    ORDER BY table_name, ordinal_position
+  `);
+
+  const schema: TableSchema = {};
+
+  for (const row of result.rows) {
+    if (!schema[row.table_name]) {
+      schema[row.table_name] = [];
+    }
+
+    schema[row.table_name].push({
+      name: row.column_name,
+      type: mapPgTypeToTs(row.data_type),
+      nullable: row.is_nullable === "YES",
+    });
+  }
+
+  return schema;
+}
+
+function mapPgTypeToTs(pgType: string): string {
+  const typeMap: { [key: string]: string } = {
+    bigint: "number",
+    integer: "number",
+    smallint: "number",
+    numeric: "number",
+    decimal: "number",
+    real: "number",
+    "double precision": "number",
+    boolean: "boolean",
+    text: "string",
+    varchar: "string",
+    char: "string",
+    "character varying": "string",
+    timestamp: "Date",
+    "timestamp without time zone": "Date",
+    "timestamp with time zone": "Date",
+    date: "Date",
+    time: "string",
+    "time without time zone": "string",
+    "time with time zone": "string",
+    json: "Record<string, any>",
+    jsonb: "Record<string, any>",
+    uuid: "string",
+  };
+
+  return typeMap[pgType] || "any";
+}
