+++ b/src/db/typed-query.ts
@@ -0,0 +1,41 @@
+import { Pool, QueryResult } from "pg";
+import { introspectSchema, type TableSchema } from "./schema-gen.js";
+import { validateQuery } from "./query-validator.js";
+
+export class TypedQueryExecutor {
+  private schema: TableSchema | null = null;
+  private schemaInitialized = false;
+
+  constructor(private pool: Pool) {}
+
+  async ensureSchema(): Promise<void> {
+    if (this.schemaInitialized) return;
+
+    this.schema = await introspectSchema(this.pool);
+    this.schemaInitialized = true;
+  }
+
+  async query<T>(sql: string, values?: unknown[]): Promise<QueryResult<T>> {
+    await this.ensureSchema();
+
+    if (this.schema) {
+      validateQuery(sql, this.schema);
+    }
+
+    return this.pool.query<T>(sql, values);
+  }
+
+  async one<T>(sql: string, values?: unknown[]): Promise<T | null> {
+    const result = await this.query<T>(sql, values);
+    return result.rows[0] ?? null;
+  }
+
+  async many<T>(sql: string, values?: unknown[]): Promise<T[]> {
+    const result = await this.query<T>(sql, values);
+    return result.rows;
+  }
+}
+
+export function createTypedQueryExecutor(pool: Pool): TypedQueryExecutor {
+  return new TypedQueryExecutor(pool);
+}
